# slugify contract

`slugify(text)` must:

1. trim leading and trailing separators;
2. lowercase ASCII letters;
3. replace every run of non-alphanumeric characters with one `-`;
4. return `"item"` when no alphanumeric characters remain.

import unittest

from slug import slugify


class SlugTests(unittest.TestCase):
    def test_words(self):
        self.assertEqual("hello-world", slugify("Hello World"))


if __name__ == "__main__":
    unittest.main()

